cypher:
// person activity: PRs, posts, incidents, on-call weeks, decisions and agent findings that name them
MATCH (p:Person {uid: $uid})
CALL {
  WITH p MATCH (p)-[:AUTHORED]->(pr:PR) RETURN 'pr' AS kind, pr.uid AS uid, pr.title AS title, pr.mergedAt AS at
  UNION ALL
  WITH p MATCH (f:Finding)-[:ABOUT|SUPPORTED_BY]->(p) RETURN 'finding' AS kind, f.uid AS uid, f.claim AS title, f.createdAt AS at
}
RETURN kind, uid, title, at
ORDER BY at DESC
LIMIT $limit
